function nextVersion(current, subjects) {
  const [major, minor, patch] = current.split(".").map(Number);
  if (subjects.some((s) => /^\w+(\([\w-]+\))?!:/.test(s))) return `${major + 1}.0.0`;
  if (subjects.some((s) => /^feat(\(|:)/.test(s))) return `${major}.${minor + 1}.0`;
  if (subjects.some((s) => /^fix(\(|:)/.test(s))) return `${major}.${minor}.${patch + 1}`;
  return current;
}

