function mergeBase(parents, a, b) {
  const ancestorsOfA = new Set();
  for (let c = a; c !== null; c = parents[c]) ancestorsOfA.add(c);
  for (let c = b; c !== null; c = parents[c]) {
    if (ancestorsOfA.has(c)) return c;
  }
  return null;
}

