function takeSide(text, side) {
  const kept = [];
  let current = null;
  for (const line of text.split("\n")) {
    if (line.startsWith("<<<<<<<")) current = "head";
    else if (line === "=======") current = "incoming";
    else if (line.startsWith(">>>>>>>")) current = null;
    else if (current === null || current === side) kept.push(line);
  }
  return kept.join("\n");
}

