questions.solution:
function changelogSection(version, subjects) {
  const lines = [`## ${version}`];
  for (const [type, heading] of [["feat", "Added"], ["fix", "Fixed"]]) {
    const entries = subjects.filter((s) => new RegExp(`^${type}(\\(|:)`).test(s)).map((s) => `- ${s.slice(s.indexOf(":") + 2)}`);
    if (entries.length > 0) lines.push(`### ${heading}`, ...entries);
  }
  return lines.join("\n");
}

